package ru.focusflow.pen;
import android.app.*;import android.appwidget.*;import android.content.*;import android.os.*;import android.widget.*;import android.view.*;import org.json.*;import java.util.*;

/** Hosts ordinary Android widgets under FocusFlow's own host ID. The launcher is never changed. */
public final class WidgetActivity extends Activity {
    private static final int HOST=70219,BIND=10,CONFIGURE=11;private AppWidgetHost host;private AppWidgetManager manager;private int pending=-1,showing=-1;private String label="Виджет";
    @Override public void onCreate(Bundle saved){super.onCreate(saved);host=new AppWidgetHost(this,HOST);manager=AppWidgetManager.getInstance(this);if(saved!=null){pending=saved.getInt("pending",-1);label=saved.getString("label","Виджет");}showing=getIntent().getIntExtra("widgetId",-1);if(showing>0)display(showing);else picker();}
    private void picker(){LinearLayout p=NativeUi.page(this,"Выберите виджет");NativeUi.text(this,p,"Виджет откроется в отдельном окне FocusFlow. При первом добавлении Android запросит разрешение.");LinearLayout list=NativeUi.list(this,p);
        int[] bound=host.getAppWidgetIds();for(int id:bound){AppWidgetProviderInfo info=manager.getAppWidgetInfo(id);if(info!=null){String name=info.loadLabel(getPackageManager());NativeUi.button(this,list,"Сохранённый: "+name,()->finishPick(id,name));}}
        List<AppWidgetProviderInfo> providers=new ArrayList<>(manager.getInstalledProviders());providers.sort((a,b)->String.valueOf(a.loadLabel(getPackageManager())).compareToIgnoreCase(String.valueOf(b.loadLabel(getPackageManager()))));
        for(AppWidgetProviderInfo info:providers){String name=info.loadLabel(getPackageManager());String app;try{app=getPackageManager().getApplicationLabel(getPackageManager().getApplicationInfo(info.provider.getPackageName(),0)).toString();}catch(Exception e){app=info.provider.getPackageName();}NativeUi.button(this,list,app+" · "+name,()->bind(info,name));}
        if(providers.isEmpty())NativeUi.text(this,list,"Приложения с обычными Android-виджетами не найдены.");
    }
    private void bind(AppWidgetProviderInfo info,String name){if(pending>0)host.deleteAppWidgetId(pending);pending=host.allocateAppWidgetId();label=name;Bundle options=options();try{if(manager.bindAppWidgetIdIfAllowed(pending,info.getProfile(),info.provider,options))configure();else startActivityForResult(new Intent(AppWidgetManager.ACTION_APPWIDGET_BIND).putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,pending).putExtra(AppWidgetManager.EXTRA_APPWIDGET_PROVIDER,info.provider).putExtra(AppWidgetManager.EXTRA_APPWIDGET_PROVIDER_PROFILE,info.getProfile()).putExtra(AppWidgetManager.EXTRA_APPWIDGET_OPTIONS,options),BIND);}catch(Exception e){cancelPending();Toast.makeText(this,"Не удалось добавить этот виджет",1).show();}}
    private Bundle options(){int w=(int)(getResources().getDisplayMetrics().widthPixels/getResources().getDisplayMetrics().density)-32;Bundle b=new Bundle();b.putInt(AppWidgetManager.OPTION_APPWIDGET_MIN_WIDTH,Math.max(200,w));b.putInt(AppWidgetManager.OPTION_APPWIDGET_MAX_WIDTH,Math.max(200,w));b.putInt(AppWidgetManager.OPTION_APPWIDGET_MIN_HEIGHT,250);b.putInt(AppWidgetManager.OPTION_APPWIDGET_MAX_HEIGHT,600);b.putInt(AppWidgetManager.OPTION_APPWIDGET_HOST_CATEGORY,AppWidgetProviderInfo.WIDGET_CATEGORY_HOME_SCREEN);return b;}
    private void configure(){AppWidgetProviderInfo info=manager.getAppWidgetInfo(pending);if(info==null){cancelPending();return;}if(info.configure!=null){try{host.startAppWidgetConfigureActivityForResult(this,pending,0,CONFIGURE,null);}catch(Exception e){cancelPending();Toast.makeText(this,"Настройка виджета недоступна",1).show();}}else{int id=pending;pending=-1;finishPick(id,label);}}
    private void finishPick(int id,String name){setResult(RESULT_OK,new Intent().putExtra("type","widget").putExtra("value",String.valueOf(id)).putExtra("label","Виджет: "+name));finish();}
    private void cancelPending(){if(pending>0)host.deleteAppWidgetId(pending);pending=-1;}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==BIND){if(result==RESULT_OK)configure();else cancelPending();}else if(request==CONFIGURE){if(result==RESULT_OK){int id=pending;pending=-1;finishPick(id,label);}else cancelPending();}}
    private void display(int id){AppWidgetProviderInfo info=manager.getAppWidgetInfo(id);LinearLayout p=NativeUi.page(this,info==null?"Виджет недоступен":info.loadLabel(getPackageManager()));NativeUi.button(this,p,"Закрыть",this::finish);if(info==null){NativeUi.text(this,p,"Добавьте виджет заново в редакторе действий.");return;}AppWidgetHostView v=host.createView(this,id,info);v.setAppWidget(id,info);p.addView(v,new LinearLayout.LayoutParams(-1,0,1));v.post(()->{int w=(int)(v.getWidth()/getResources().getDisplayMetrics().density),h=(int)(v.getHeight()/getResources().getDisplayMetrics().density);v.updateAppWidgetSize(null,w,h,w,h);});}
    @Override protected void onStart(){super.onStart();host.startListening();}@Override protected void onStop(){host.stopListening();super.onStop();}
    @Override protected void onSaveInstanceState(Bundle b){b.putInt("pending",pending);b.putString("label",label);super.onSaveInstanceState(b);}
    @Override public void onBackPressed(){if(showing<0)cancelPending();super.onBackPressed();}
    @Override protected void onDestroy(){if(isFinishing())cancelPending();super.onDestroy();}
}
